pairs = [
    (".sf-subtitle-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:11px}", ".sf-subtitle-heading{display:grid;grid-template-columns:minmax(0,min(800px,max(520px,calc((100dvh - 470px)*16/9)))) minmax(235px,1fr);align-items:center;gap:10px;margin-bottom:11px}\n.sf-subtitle-heading .sf-subtitle-reset{justify-self:end}\n.sf-subtitle-preview-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;min-width:0}\n.sf-subtitle-scene-toggle{display:inline-grid;grid-template-columns:1fr 1fr;align-items:center;position:relative;isolation:isolate;flex:none;min-height:32px;min-width:112px;padding:3px;border:1px solid var(--line);border-radius:10px;background:var(--surface);color:var(--muted);font-size:11px;font-weight:660}\n.sf-subtitle-scene-toggle::before{content:\"\";position:absolute;z-index:-1;inset:3px 50% 3px 3px;border-radius:7px;background:var(--raised);border:1px solid var(--line)}\n.sf-subtitle-scene-toggle[aria-checked=\"true\"]::before{inset:3px 3px 3px 50%}\n.sf-subtitle-scene-toggle[aria-checked=\"false\"] .scene-day,.sf-subtitle-scene-toggle[aria-checked=\"true\"] .scene-night{color:var(--ink)}\n.sf-subtitle-scene-toggle:hover{border-color:var(--accent)}\n.sf-subtitle-scene-toggle:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n.subtitle-expanded-scene-heading{display:flex;justify-content:flex-end;margin:0 0 10px}\n.subtitle-stage-night{transition:none!important}\n@container (max-width:1030px){.sf-subtitle-heading{display:flex;justify-content:space-between}.sf-subtitle-preview-heading .sf-subtitle-scene-toggle{display:none}}"),
    ("<div><h3><span class=\"sf-subtitle-full-title\">Live subtitle preview</span><span class=\"sf-subtitle-compact-title\">Subtitle appearance</span></h3>\n     <p><span class=\"sf-subtitle-full-description\">Automatically cycles between the bright and dark shrine scenes.</span><span class=\"sf-subtitle-compact-description\">Fine-tune your subtitles, then open the preview to inspect the results.</span></p>\n    </div>", "<div class=\"sf-subtitle-preview-heading\"><div><h3><span class=\"sf-subtitle-full-title\">Subtitle preview</span><span class=\"sf-subtitle-compact-title\">Subtitle appearance</span></h3>\n     <p class=\"sf-subtitle-compact-description\">Fine-tune your subtitles, then open the preview to inspect the results.</p>\n    </div>${subtitleSceneToggle()}</div>"),
    ("aria-label=\"Live subtitle preview with synchronized automatic day and night shrine scenes\"", "aria-label=\"Subtitle preview\""),
    ("/* v91 — One shared value drives both night layers on the SAME frame.\n   Unlike v90, there are no independent CSS animation objects to synchronize.\n   Keep the agreed comparison timing: 4.8s fades + 1.7s holds = 13s loop.\n   Match the comparison's actual smoothstep easing (3t² − 2t³). */\nconst SUBTITLE_FADE_MS=4800;\nconst SUBTITLE_HOLD_MS=1700;\nconst SUBTITLE_LOOP_MS=2*(SUBTITLE_FADE_MS+SUBTITLE_HOLD_MS);\nconst subtitleReducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');\nlet subtitleCycleStartTime=null;\nlet subtitleCycleFrame=null;\nfunction subtitleNightMix(time){\n if(subtitleReducedMotion.matches)return 0;\n if(subtitleCycleStartTime===null)subtitleCycleStartTime=time;\n const t=((time-subtitleCycleStartTime)%SUBTITLE_LOOP_MS+SUBTITLE_LOOP_MS)%SUBTITLE_LOOP_MS;\n const smooth=x=>x*x*(3-2*x);\n if(t<SUBTITLE_FADE_MS)return smooth(t/SUBTITLE_FADE_MS);\n if(t<SUBTITLE_FADE_MS+SUBTITLE_HOLD_MS)return 1;\n if(t<2*SUBTITLE_FADE_MS+SUBTITLE_HOLD_MS)return 1-smooth((t-SUBTITLE_FADE_MS-SUBTITLE_HOLD_MS)/SUBTITLE_FADE_MS);\n return 0;\n}\nfunction subtitleStages(){\n return [settingsPage.querySelector('#subtitle-preview-stage'),modalHost.querySelector('#subtitle-expanded-stage')].filter(Boolean);\n}\nfunction subtitleCycleIsVisible(){\n return !!modalHost.querySelector('#subtitle-expanded-stage') ||\n  (document.body.classList.contains('settings-view') && !settingsClosing &&\n   settingsLastSection==='playback' && playbackTab==='subtitles');\n}\nfunction paintSubtitleNight(time){\n const opacity=subtitleNightMix(time).toFixed(6);\n // Paint one identical numeric value to both layers, never separate calculations.\n for(const stage of subtitleStages()){\n  const layer=stage.querySelector('.subtitle-stage-night');\n  if(layer && layer.style.opacity!==opacity)layer.style.opacity=opacity;\n }\n}\nfunction tickSubtitleNight(time){\n subtitleCycleFrame=null;\n if(document.hidden || subtitleReducedMotion.matches || !subtitleCycleIsVisible())return;\n paintSubtitleNight(time);\n subtitleCycleFrame=requestAnimationFrame(tickSubtitleNight);\n}\nfunction updateSharedSubtitleClock(){\n paintSubtitleNight(performance.now());\n if(subtitleCycleFrame===null && !document.hidden &&\n    !subtitleReducedMotion.matches && subtitleCycleIsVisible())\n  subtitleCycleFrame=requestAnimationFrame(tickSubtitleNight);\n}\nsubtitleReducedMotion.addEventListener('change',()=>{\n if(subtitleCycleFrame!==null){cancelAnimationFrame(subtitleCycleFrame);subtitleCycleFrame=null;}\n updateSharedSubtitleClock();\n});\ndocument.addEventListener('visibilitychange',()=>{\n if(document.hidden && subtitleCycleFrame!==null){cancelAnimationFrame(subtitleCycleFrame);subtitleCycleFrame=null;}\n else if(!document.hidden)updateSharedSubtitleClock();\n});\n", "// One manually selected scene is shared by both preview surfaces.\nlet subtitlePreviewScene='day';\nfunction subtitleSceneToggle(){\n return `<button type=\"button\" role=\"switch\" class=\"sf-subtitle-scene-toggle\" aria-label=\"Night preview\" aria-checked=\"${subtitlePreviewScene==='night'}\"><span class=\"scene-day\" aria-hidden=\"true\">Day</span><span class=\"scene-night\" aria-hidden=\"true\">Night</span></button>`;\n}\nfunction subtitleStages(){\n return [settingsPage.querySelector('#subtitle-preview-stage'),modalHost.querySelector('#subtitle-expanded-stage')].filter(Boolean);\n}\nfunction applySubtitlePreviewScene(){\n const night=subtitlePreviewScene==='night';\n for(const stage of subtitleStages()){\n  const layer=stage.querySelector('.subtitle-stage-night');\n  if(layer)layer.style.opacity=night?'1':'0';\n }\n for(const root of [settingsPage,modalHost]){\n  for(const toggle of root.querySelectorAll('.sf-subtitle-scene-toggle'))toggle.setAttribute('aria-checked',String(night));\n }\n}\nfunction bindSubtitleSceneToggle(root){\n for(const toggle of root.querySelectorAll('.sf-subtitle-scene-toggle'))toggle.addEventListener('click',()=>{\n  subtitlePreviewScene=subtitlePreviewScene==='night'?'day':'night';\n  applySubtitlePreviewScene();\n });\n}\n"),
    (" updateSharedSubtitleClock();", " applySubtitlePreviewScene();"),
    ("modal('Expanded subtitle preview',`<p class=\"subtitle-expanded-note\">Inspect the subtitle effect against the same automatic day/night shrine scenes at a larger size.</p>", "modal('Expanded subtitle preview',`<div class=\"subtitle-expanded-scene-heading\">${subtitleSceneToggle()}</div>"),
    ("aria-label=\"Expanded live subtitle preview with automatic day and night crossfade\"", "aria-label=\"Expanded subtitle preview\""),
    (" dialog.classList.add('subtitle-preview-dialog');", " dialog.classList.add('subtitle-preview-dialog');\n bindSubtitleSceneToggle(dialog);"),
    (" settingsPage.querySelector('#subtitle-expand-preview')?.addEventListener('click',showExpandedSubtitlePreview);", " bindSubtitleSceneToggle(settingsPage);\n settingsPage.querySelector('#subtitle-expand-preview')?.addEventListener('click',showExpandedSubtitlePreview);"),
]
for old,new in pairs:
    assert source.count(old) == 1, old[:100]
    source = source.replace(old,new,1)
assert "subtitleCycleFrame" not in source and "SUBTITLE_FADE_MS" not in source
assert "Automatically cycles between" not in source
full = source.encode("utf-8")
template = full
for name, sha in (("day","0bd22bbc4f21a48b3ee2c451995814ab5fc0406745b653eecf5a0dc834bfe4ae"),("night","3f37dcb26d19f07cabe7283d7894635f712649bc7caab68610bb11541e0171e4")):
    asset = (root / "assets/subtitle-preview" / f"shrine-{name}.png").read_bytes()
    assert hashlib.sha256(asset).hexdigest() == sha
    url = b"data:image/png;base64," + base64.b64encode(asset)
    assert template.count(url) == 1
    template = template.replace(url, f"__GALLERY_SHRINE_{name.upper()}_DATA_URL__".encode(), 1)
builder = root / "tools/build-gallery.py"
assert builder.read_text() == "#!/usr/bin/env python3\n\"\"\"Deterministic standalone Gallery HTML builds; canonical checkpoint stays authoritative.\"\"\"\nimport argparse\nimport base64\nimport hashlib\nimport json\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\nTEMPLATE = ROOT / \"src/Gallery.template.html\"\nCANONICAL = ROOT / \"Gallery-current.html\"\nDEVELOPMENT = ROOT / \"Gallery-development.html\"\nASSETS = ROOT / \"assets/subtitle-preview\"\nMODES = (\"development\", \"subtitle-preview\", \"full\")\nTOKENS = {\n    \"day\": b\"__GALLERY_SHRINE_DAY_DATA_URL__\",\n    \"night\": b\"__GALLERY_SHRINE_NIGHT_DATA_URL__\",\n}\nCOLORS = {\"day\": b\"#d5dbe2\", \"night\": b\"#091b2c\"}\nLIGHT_PATCHES = (\n    (b\"stage.querySelector('.subtitle-stage-day').src=SHRINE_DAY_IMAGE;\",\n     b\"stage.querySelector('.subtitle-stage-day').style.backgroundColor=SHRINE_DAY_IMAGE;\"),\n    (b\"stage.querySelector('.subtitle-stage-night').src=SHRINE_NIGHT_IMAGE;\",\n     b\"stage.querySelector('.subtitle-stage-night').style.backgroundColor=SHRINE_NIGHT_IMAGE;\"),\n    (b\"d.src=SHRINE_DAY_IMAGE;n.src=SHRINE_NIGHT_IMAGE;\",\n     b\"d.style.backgroundColor=SHRINE_DAY_IMAGE;n.style.backgroundColor=SHRINE_NIGHT_IMAGE;\"),\n    (b\"synchronized automatic day and night shrine scenes\",\n     b\"synchronized automatic day and night solid backgrounds\"),\n    (b\"the same automatic day/night shrine scenes\",\n     b\"the same automatic day/night solid backgrounds\"),\n)\n\ndef replace_once(source, old, new):\n    if source.count(old) != 1:\n        raise ValueError(f\"Expected exactly one occurrence: {old[:100]!r}\")\n    return source.replace(old, new, 1)\n\ndef build(mode):\n    if mode not in MODES:\n        raise ValueError(f\"Unknown build mode: {mode}\")\n    result = TEMPLATE.read_bytes()\n    for name, token in TOKENS.items():\n        if mode == \"development\":\n            value = COLORS[name]\n        else:\n            raw = (ASSETS / f\"shrine-{name}.png\").read_bytes()\n            if not raw.startswith(b\"\\x89PNG\\r\\n\\x1a\\n\"):\n                raise ValueError(f\"Invalid original PNG: {name}\")\n            value = b\"data:image/png;base64,\" + base64.b64encode(raw)\n        result = replace_once(result, token, value)\n    if mode == \"development\":\n        for old, new in LIGHT_PATCHES:\n            result = replace_once(result, old, new)\n        if b\"data:image/png;base64,\" in result:\n            raise ValueError(\"Unexpected embedded PNG in development mode\")\n    return result\n\ndef check():\n    full = build(\"full\")\n    if full != CANONICAL.read_bytes() or full != build(\"subtitle-preview\"):\n        raise ValueError(\"Full round trip differs from canonical HTML\")\n    pointer = json.loads((ROOT / \"checkpoints/current.json\").read_text())\n    if len(full) != pointer[\"bytes\"] or hashlib.sha256(full).hexdigest() != pointer[\"sha256\"]:\n        raise ValueError(\"Full round trip differs from immutable checkpoint pointer\")\n    light = build(\"development\")\n    if light != DEVELOPMENT.read_bytes():\n        raise ValueError(\"Committed development HTML is stale; regenerate explicitly\")\n    print(f\"Full and subtitle-preview builds: {len(full)} bytes, SHA-256 {hashlib.sha256(full).hexdigest()}\")\n    print(f\"Development build: {len(light)} bytes, SHA-256 {hashlib.sha256(light).hexdigest()}\")\n    for name in TOKENS:\n        raw = (ASSETS / f\"shrine-{name}.png\").read_bytes()\n        print(f\"Original {name} PNG: {len(raw)} bytes, SHA-256 {hashlib.sha256(raw).hexdigest()}\")\n    print(\"All build modes verified; canonical HTML and checkpoint untouched.\")\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\"--mode\", choices=MODES, default=\"development\")\n    parser.add_argument(\"--output\", type=Path)\n    parser.add_argument(\"--check\", action=\"store_true\", help=\"Verify all modes without writing files\")\n    args = parser.parse_args()\n    if args.check:\n        if args.output:\n            parser.error(\"--check does not accept --output\")\n        check()\n        return\n    output = args.output or (DEVELOPMENT if args.mode == \"development\" else ROOT / \"dist\" / f\"Gallery-{args.mode}.html\")\n    output = output.resolve()\n    # Prevent this transitional builder from writing the checkpoint or canonical source.\n    protected = (CANONICAL.resolve(), TEMPLATE.resolve())\n    if output in protected or any(p in output.parents for p in (ROOT / \"checkpoints\", ROOT / \"assets\", ROOT / \"src\")):\n        parser.error(\"Output cannot overwrite canonical source, assets or checkpoints\")\n    result = build(args.mode)\n    output.parent.mkdir(parents=True, exist_ok=True)\n    output.write_bytes(result)\n    print(f\"{output}: {len(result)} bytes, SHA-256 {hashlib.sha256(result).hexdigest()}\")\n\nif __name__ == \"__main__\":\n    main()\n"
builder.write_text("#!/usr/bin/env python3\n\"\"\"Deterministic standalone Gallery HTML builds; canonical checkpoint stays authoritative.\"\"\"\nimport argparse\nimport base64\nimport hashlib\nimport json\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\nTEMPLATE = ROOT / \"src/Gallery.template.html\"\nCANONICAL = ROOT / \"Gallery-current.html\"\nDEVELOPMENT = ROOT / \"Gallery-development.html\"\nASSETS = ROOT / \"assets/subtitle-preview\"\nMODES = (\"development\", \"subtitle-preview\", \"full\")\nTOKENS = {\n    \"day\": b\"__GALLERY_SHRINE_DAY_DATA_URL__\",\n    \"night\": b\"__GALLERY_SHRINE_NIGHT_DATA_URL__\",\n}\nCOLORS = {\"day\": b\"#d5dbe2\", \"night\": b\"#091b2c\"}\nLIGHT_PATCHES = (\n    (b\"stage.querySelector('.subtitle-stage-day').src=SHRINE_DAY_IMAGE;\",\n     b\"stage.querySelector('.subtitle-stage-day').style.backgroundColor=SHRINE_DAY_IMAGE;\"),\n    (b\"stage.querySelector('.subtitle-stage-night').src=SHRINE_NIGHT_IMAGE;\",\n     b\"stage.querySelector('.subtitle-stage-night').style.backgroundColor=SHRINE_NIGHT_IMAGE;\"),\n    (b\"d.src=SHRINE_DAY_IMAGE;n.src=SHRINE_NIGHT_IMAGE;\",\n     b\"d.style.backgroundColor=SHRINE_DAY_IMAGE;n.style.backgroundColor=SHRINE_NIGHT_IMAGE;\"),\n)\n\ndef replace_once(source, old, new):\n    if source.count(old) != 1:\n        raise ValueError(f\"Expected exactly one occurrence: {old[:100]!r}\")\n    return source.replace(old, new, 1)\n\ndef build(mode):\n    if mode not in MODES:\n        raise ValueError(f\"Unknown build mode: {mode}\")\n    result = TEMPLATE.read_bytes()\n    for name, token in TOKENS.items():\n        if mode == \"development\":\n            value = COLORS[name]\n        else:\n            raw = (ASSETS / f\"shrine-{name}.png\").read_bytes()\n            if not raw.startswith(b\"\\x89PNG\\r\\n\\x1a\\n\"):\n                raise ValueError(f\"Invalid original PNG: {name}\")\n            value = b\"data:image/png;base64,\" + base64.b64encode(raw)\n        result = replace_once(result, token, value)\n    if mode == \"development\":\n        for old, new in LIGHT_PATCHES:\n            result = replace_once(result, old, new)\n        if b\"data:image/png;base64,\" in result:\n            raise ValueError(\"Unexpected embedded PNG in development mode\")\n    return result\n\ndef check():\n    full = build(\"full\")\n    if full != CANONICAL.read_bytes() or full != build(\"subtitle-preview\"):\n        raise ValueError(\"Full round trip differs from canonical HTML\")\n    pointer = json.loads((ROOT / \"checkpoints/current.json\").read_text())\n    if len(full) != pointer[\"bytes\"] or hashlib.sha256(full).hexdigest() != pointer[\"sha256\"]:\n        raise ValueError(\"Full round trip differs from immutable checkpoint pointer\")\n    light = build(\"development\")\n    if light != DEVELOPMENT.read_bytes():\n        raise ValueError(\"Committed development HTML is stale; regenerate explicitly\")\n    print(f\"Full and subtitle-preview builds: {len(full)} bytes, SHA-256 {hashlib.sha256(full).hexdigest()}\")\n    print(f\"Development build: {len(light)} bytes, SHA-256 {hashlib.sha256(light).hexdigest()}\")\n    for name in TOKENS:\n        raw = (ASSETS / f\"shrine-{name}.png\").read_bytes()\n        print(f\"Original {name} PNG: {len(raw)} bytes, SHA-256 {hashlib.sha256(raw).hexdigest()}\")\n    print(\"All build modes verified; canonical HTML and checkpoint untouched.\")\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\"--mode\", choices=MODES, default=\"development\")\n    parser.add_argument(\"--output\", type=Path)\n    parser.add_argument(\"--check\", action=\"store_true\", help=\"Verify all modes without writing files\")\n    args = parser.parse_args()\n    if args.check:\n        if args.output:\n            parser.error(\"--check does not accept --output\")\n        check()\n        return\n    output = args.output or (DEVELOPMENT if args.mode == \"development\" else ROOT / \"dist\" / f\"Gallery-{args.mode}.html\")\n    output = output.resolve()\n    # Prevent this transitional builder from writing the checkpoint or canonical source.\n    protected = (CANONICAL.resolve(), TEMPLATE.resolve())\n    if output in protected or any(p in output.parents for p in (ROOT / \"checkpoints\", ROOT / \"assets\", ROOT / \"src\")):\n        parser.error(\"Output cannot overwrite canonical source, assets or checkpoints\")\n    result = build(args.mode)\n    output.parent.mkdir(parents=True, exist_ok=True)\n    output.write_bytes(result)\n    print(f\"{output}: {len(result)} bytes, SHA-256 {hashlib.sha256(result).hexdigest()}\")\n\nif __name__ == \"__main__\":\n    main()\n", encoding="utf-8")
